oxy_webhelp_navlinks = {"tocId-d39307e17975":{"topics":[{"title":"SLA Domains for RSC-managed AWS accounts","shortdesc":"<p class=\"shortdesc\">SLA Domains for RSC-managed accounts archive to Rubrik Cloud Vault by default and do         not support replication.<\/p>","href":"saas\/aws_hosted_sla_domains.html","attributes":{"data-id":"aws_hosted_sla_domains"},"menu":{"hasChildren":false},"tocID":"aws_hosted_sla_domains-d39307e17976","topics":[]},{"title":"Default SLA Domains for RSC-managed AWS accounts","shortdesc":"<p class=\"shortdesc\">Rubrik Default SLA Domains are pre-configured for each supported workload type in         RSC-managed accounts.<\/p>","href":"saas\/aws_hosted_default_sla_domains.html","attributes":{"data-id":"aws_hosted_default_sla_domains"},"menu":{"hasChildren":false},"tocID":"aws_hosted_default_sla_domains-d39307e17987","topics":[]},{"title":"Creating an <span class=\"ph\">RSC<\/span>-managed SLA Domain for AWS","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain for AWS accounts that use the <span class=\"ph\">RSC<\/span>-managed         deployment model, so that <span class=\"ph\">RSC<\/span> archives your backups to Rubrik Cloud Vault or         to storage that you own.<\/p>","href":"saas\/aws_rsc_managed_creating_sla.html","attributes":{"data-id":"aws_rsc_managed_creating_sla"},"menu":{"hasChildren":false},"tocID":"aws_rsc_managed_creating_sla-d39307e17998","topics":[]},{"title":"Creating a self-managed SLA Domain for AWS","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain to streamline and customize workload protection and         management policies for AWS accounts that use the self-managed deployment model.<\/p>","href":"saas\/aws_creating_custom_sla.html","attributes":{"data-id":"aws_creating_custom_sla"},"menu":{"hasChildren":false},"tocID":"aws_creating_custom_sla-d39307e18018","topics":[]},{"title":"Evaluate AWS SLA Domain options","shortdesc":"<p class=\"shortdesc\">Understanding the various protection options is important when creating an SLA Domain         for your AWS workloads. This ensures alignment with organizational needs. Thoroughly         evaluating these options enables informed decisions and provides effective protection for         the workloads.<\/p>","href":"saas\/aws_evaluate_sla_option.html","attributes":{"data-id":"aws_evaluate_sla_option"},"menu":{"hasChildren":false},"tocID":"aws_evaluate_sla_option-d39307e18029","next":"aws_evaluate_sla_option-d39307e18029"},{"title":"Creating an SLA Domain for Iceberg tables","shortdesc":"<p class=\"shortdesc\">Create a custom SLA Domain to define snapshot frequency, retention, and backup         policies for your AWS Glue Tables and AWS S3 Tables Iceberg workloads.<\/p>","href":"aws\/aws_iceberg_creating_sla_domain.html","attributes":{"data-id":"aws_iceberg_creating_sla_domain"},"menu":{"hasChildren":false},"tocID":"aws_iceberg_creating_sla_domain-d39307e18253","topics":[]},{"title":"Creating SLA Domains without snapshot schedules ","shortdesc":"<p class=\"shortdesc\">Create an SLA Domain without snapshot schedules for Continuous Data Protection-only         SLA Domains.<\/p>","href":"saas\/creating_sla_domains_without_snapshot_schedules_2.html","attributes":{"data-id":"creating_sla_domains_without_snapshot_schedules"},"menu":{"hasChildren":false},"tocID":"creating_sla_domains_without_snapshot_schedules-d39307e18264","topics":[]},{"title":"Sharing KMS keys for cross-account operations","shortdesc":"<p class=\"shortdesc\">When replicating or exporting AWS EC2 instance and EBS volume snapshots to a         different account, you must share the customer-managed KMS keys with the target AWS account         to enable <span class=\"ph\">RSC<\/span> to read the encrypted snapshot in the target account.<\/p>","href":"saas\/aws_sharing_keys_cross_acc_replication.html","attributes":{"data-id":"aws_sharing_keys_cross_acc_replication"},"menu":{"hasChildren":false},"tocID":"aws_sharing_keys_cross_acc_replication-d39307e18275","topics":[]}]}};